/**
	Replaces any \Xdd..\ HL7 escape sequences with the corresponding character(s).

	@param {XML} node - The node to recursively iterate through.
	@param {String} charset - The character encoding set to use when converting bytes to Unicode code
		points. If not specified, US-ASCII will be used.
	@param {String} encodingCharacters - The HL7 encoding characters to exclude from the replacement.
*/
function unescapeXSequences(node, charset, encodingCharacters) {
	if (!charset) {
		charset = 'US-ASCII';
	}

	if (!encodingCharacters) {
		encodingCharacters = node.MSH['MSH.1'].toString().split('').concat(node.MSH['MSH.2'].toString().split(''));
		if (encodingCharacters.length == 0) {
			encodingCharacters = ['|', '^', '~', '\\', '&'];
		}
	}

	for each (child in node.children()) {
		if (child.hasComplexContent()) {
			unescapeXSequences(child, charset, encodingCharacters);
		} else if (!/MSH\.[12]/.test(child.name())) {
			var childString = child.toString();
			var matched = false;

			for each (match in childString.match(/\\X([\dA-F]{2})+\\/ig)) {
				matched = true;
				var hexString = match.substr(2, match.length-3);
				var buffer = java.nio.ByteBuffer.allocate(hexString.length / 2);

				while (hexString.length > 0) {
					var intValue = new java.lang.Integer((java.lang.Character.digit(hexString.substr(0,1), 16) << 4) + java.lang.Character.digit(hexString.substr(1,1), 16));
					buffer.put(intValue.byteValue());
					hexString = hexString.substr(2);
				}

				childString = childString.replace(match, new java.lang.String(buffer.array(), charset));
			}

			if (matched) {
				if (encodingCharacters.length > 3) {
					childString = childString.replace(encodingCharacters[3], '\\E\\');
				}
				if (encodingCharacters.length > 0) {
					childString = childString.replace(encodingCharacters[0], '\\F\\');
				}
				if (encodingCharacters.length > 1) {
					childString = childString.replace(encodingCharacters[1], '\\S\\');
				}
				if (encodingCharacters.length > 2) {
					childString = childString.replace(encodingCharacters[2], '\\R\\');
				}
				if (encodingCharacters.length > 4) {
					childString = childString.replace(encodingCharacters[4], '\\T\\');
				}

				node.children()[child.childIndex()] = <{child.name()}>{childString}</{child.name()}>;
			}
		}
	}
}

/**
	Returns the string representation of each child element of <b>xml</b> joined by
	<b>separator</b>. If <b>xml</b> contains no child elements, the string
	representation of <b>xml</b> will be returned instead.

	@copyright 2018 Tony Germano
	@license MPL-2.0

	@param {XML} xml - The e4x xml node representing a field component.
	@param {String} separator - Optional character used to join sub-components. Default: '&'.
	@return {String} 
*/
function joinSubcomponents(xml, separator)  {
	if (typeof separator == 'undefined') separator = '&';
	if (xml.hasComplexContent()) {
		var content = [];
		for each (var child in xml.children()) {
			content.push(child.toString());
		}
		xml = content.join(separator);
	} 
	return xml.toString();
}

/**
	Improved XMLList filter over built-in e4x filters.

        @copyright 2020 Tony Germano
        @license MPL-2.0

	@param {XMLList} xmlList - The XMLList to be filtered
	@param {Function} callback - Function is a predicate, to test each node of the XMLList. Return
		true to keep the element, false otherwise. It accepts 3 arguments - the node, the index of the node,
		and xmlList as passed into xFilter
	@param {Number} minLimit - (Optional) throw RangeError if at least this many nodes do not pass the
		filter
	@param {Number} maxReturned - (Optional) only return up to this many results
	@param {Boolean} enforceMax - (Optional) throw RangeError if more than maxReturned results will
		be returned
	@return {XMLList} new XMLList containing filtered results
*/
function xFilter(xmlList, callback, minLimit, maxReturned, enforceMax) {
    var ret = new XMLList();
    for (var i = 0; i < xmlList.length(); i++) {
        var node = xmlList[i];
        if (callback(node, i, xmlList)) {
            ret += node;
            if (enforceMax) {
                if (ret.length() > maxReturned) {
                    throw new RangeError('The number of filtered results is more than ' + maxReturned);
                }
            }
            else if (ret.length() == maxReturned) {
                break;
            }
        }
    }
    if (ret.length() < minLimit) {
        throw new RangeError('The number of filtered results is less than ' + minLimit);
    }
    return ret;
}

/**
	Creates a new segment with the given name and inserts it before the given segment.

	@param {String} insertSegmentName - The name of the new segment to insert.
	@param {XML} beforeThisSegment - The segment to insert just before.
	@return {XML} The newly created segment.
*/
function createSegmentBefore(insertSegmentName, beforeThisSegment) {
	var msgObj = beforeThisSegment;
	while (msgObj.parent() != undefined) {
		msgObj = msgObj.parent();
	}
	msgObj.insertChildBefore(beforeThisSegment[0], new XML('<' + insertSegmentName + '></' + insertSegmentName + '>'));
	return msgObj.child(beforeThisSegment[0].childIndex() - 1);
}

/**
	Inserts a given segment before a particular segment.

	@param {XML} insertSegment - The segment to insert.
	@param {XML} beforeThisSegment - The segment before which to insert the new segment.
	@return {XML} The newly inserted segment.
*/
function insertSegmentBefore(insertSegment, beforeThisSegment) {
	var msgObj = beforeThisSegment;
	while (msgObj.parent() != undefined) {
		msgObj = msgObj.parent();
	}
	msgObj.insertChildBefore(beforeThisSegment[0], insertSegment);
	return msgObj.child(beforeThisSegment[0].childIndex() - 1);
}

/**
	Inserts a given segment after a particular segment.

	@param {XML} insertSegment - The segment to insert.
	@param {XML} afterThisSegment - The segment after which to insert the new segment.
	@return {XML} The newly inserted segment.
*/
function insertSegmentAfter(insertSegment, afterThisSegment) {
	var msgObj = afterThisSegment;
	while (msgObj.parent() != undefined) {
		msgObj = msgObj.parent();
	}
	msgObj.insertChildAfter(afterThisSegment[0], insertSegment);
	return msgObj.child(afterThisSegment[0].childIndex() + 1);
}

/**
	Recursively iterates through all descendant nodes of an E4X XML object and removes those that are
	empty (or those whose children are all empty).

	@param {XML} node - The node to iterate through. If node itself is empty, it will not be removed from its parent.
	@param {Boolean} stripWhitespaceNodes - If true, nodes that are not empty but only contain whitespace will also be removed.
	@param {Boolean} onlyDeleteTrailing - If true, only trailing nodes will actually be deleted.
*/
function stripEmptyNodes(node, stripWhitespaceNodes, onlyDeleteTrailing) {
	var nonEmptyFound = false;

	for (var childIndex = node.children().length()-1; childIndex >= 0; childIndex--) {
		var child = node.children()[childIndex];
		stripEmptyNodes(child, stripWhitespaceNodes, onlyDeleteTrailing);

		if (stripWhitespaceNodes && !child.toString().trim() || !stripWhitespaceNodes && !child.toString()) {
			if (!nonEmptyFound || !onlyDeleteTrailing) {
				delete node.children()[childIndex];
			} else {
				node.children()[childIndex] = new XML('<'+child.name().toString()+'/>');
			}
		} else {
			nonEmptyFound = true;
		}
	}
}

