/**
 * Exchanges a JWT assertion for an access token.
 *
 * @param jwtAssertion The signed JWT assertion
 * @return             The access token or null if failed
 */
private String getAccessToken(String jwtAssertion) {
    try {
        URL tokenUrl = new URL("https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4/oauth2/token");
        HttpURLConnection conn = (HttpURLConnection) tokenUrl.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
        conn.setDoOutput(true);

        String urlParameters = "grant_type=client_credentials&client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer&client_assertion=" + jwtAssertion;

        try (OutputStream os = conn.getOutputStream()) {
            byte[] input = urlParameters.getBytes("utf-8");
            os.write(input, 0, input.length);
        }

        int responseCode = conn.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            try (BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
                String inputLine;
                StringBuilder response = new StringBuilder();

                while ((inputLine = in.readLine()) != null) {
                    response.append(inputLine);
                }

                // Parse the JSON response to extract the access token
                JSONObject jsonResponse = new JSONObject(response.toString());
                return jsonResponse.getString("access_token");
            }
        } else {
            log.error("Failed to exchange JWT for access token. Response code: " + responseCode);
        }
    } catch (IOException e) {
        log.error("Error exchanging JWT for access token", e);
    }

    return null;
}

